INSERT INTO social_and_env_grieviancemonitoringlog (case_no, sex, date_claim_recieved, name_of_person_receiving_complaint, how_complaint_was_received, name_of_complainant, tell_no, complaint_content, was_recieved_of_complaint_ack, expected_decision_date, was_decison_communicated_to_complainant, communication_method, was_complainant_satisfied_with_decision, brief_note_for_NO_answer, any_follow_up_action, date_created, decision_outcome_id, loginUser_id, project_id, type_of_investment_id) VALUES ('GR-TL146', 'M', '2023-06-07', 'Nuha Colley', 'Letter', 'Bakary Jawneh', '7733048', 'In a letter to the GRC, Bakary rejected the proposed D501,725 claiming for a compensation of 1.3 million for his fenced 30m X 35m property in Jambur', 'Y', '2023-06-23', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-04-28 14:19:34.2840320 ', 20009, 21, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL147', 'M', '2023-06-07', 'Nuha Colley', 'Letter', 'Mamadou Barry', '7810097/3563651', 'Mr Barry was contacted to proposed a fair compensation in writing which he  failed and on the 10/06/2023 he was called again to provide a written claim and was informed that the GRC will visit his property.', 'Y', '2023-06-22', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-04-28 14:27:06.0319800 ', 20009, 21, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL148', 'F', '2023-06-09', 'Nuha Colley', 'Letter', 'Jainaba Jallow', '3506093', 'Jainaba in a letter to the GRC claimed for a compensation amount of D2.2million for her 90m X 30m property in Jambur. She argued that the proposed D945,000 compensation was not enough to earn her a land of this size anywhere in kombo', 'Y', '2023-06-23', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-04-28 14:35:41.5845660 ', 20009, 21, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL149', 'M', '2023-06-09', 'Nuha Colley', 'Letter', 'Karafa Tamba', '2000044/9804744', 'Karafa live near to a pylon area and during the mounting the pylon the contractors destroyed his fence and some trees in his property. In a letter to the GRC karafa claimed D135,000 for material damage.', 'Y', '2023-06-22', 'Y', 'Call', 'N', 'Still pended by the contractor.', 'Open', '2025-04-28 14:42:46.9606270 ', 20008, 21, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL150', 'F', '2023-06-09', 'Nuha Colley', 'Letter', 'Jainaba Bah', '3233684', 'Jainaba Bah whose 32m X 33m property was impacted in Latriya. In a letter to the GRC claimed for a compensation of D900,000 instead of the proposed D375,200', 'Y', '2023-06-22', 'Y', 'In Person', 'Y', 'Not applicable', 'Open', '2025-04-28 14:46:17.9092280 ', 20009, 21, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL151', 'M', '2023-06-12', 'Nuha Colley', 'Letter', 'Ousman wuyeh Ba Darboe', '3708113', 'Ousman in a letter to the GRC claimed for D100,000 instead of the proposed D7,735 for 25m X 4m impacted by the project claiming that the proposed amount was not a fair compensation for his property.', 'Y', '2023-06-22', 'Y', 'In Person', 'Y', 'Not applicable', 'Open', '2025-04-28 14:51:09.9309720 ', 20009, 21, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL152', 'M', '2023-06-12', 'Nuha Colley', 'Letter', 'Yusupha Jammeh C/O Ebrima Camara', '7016242', 'He claimed that D900,000 will be a fair compensation as per a valuation by one karafa sambou of the Department of Physical Planning.', 'Y', '2023-06-22', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-04-28 15:03:30.8445420 ', 20009, 21, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL153', 'M', '2023-06-12', 'Nuha Colley', 'Letter', 'Awa Cham C/O Madikay Sallah', '7204914/3628359', 'Awa wrote to claim D3.5million rejecting the proposed D1,462.350 disclosed to her. Siting the prices of buliding material and tha fact tha almost all her property will be lsot to the project.', 'Y', '2023-06-22', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-04-28 15:11:01.4274990 ', 20009, 21, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL154', 'M', '2023-06-17', 'Nuha Colley', 'Letter', 'Mustapha Jammeh C/O Gibril Bah', '3075660/702895', 'In a letter to the GRC Mr Jammeh wrote to disagreed to the offer and claimed D2.4M  citing the location of the plot Is in a high value considering the proximity of both water and electricity', 'Y', '2023-06-22', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-04-28 15:14:18.8138080 ', 20009, 21, 'D309& D6530 -GM', 'GERMP T&D'), ('GR-TL156', 'M', '2023-06-20', 'Nuha Colley', 'mail', 'Muhammed Mboob C/O Oumie Mboob', '2026892', 'Mr Mboob is claiming D700,000.00 on his land measuring 20m+25m on a letter sent to GRC dated 15/6/2023', 'Y', '2023-06-20', 'Y', 'In Person', 'Y', 'Not applicable', 'Closed.', '2025-04-28 15:19:08.4005750 ', 20009, 21, 'D309& D6530 -GM', 'GERMP T&D');